if (owned == 1) { FUZZ_BAIL(); }

// Safe to free the object
json_free(o);
// Validation: prevents double-free/invalid-free by honoring ownership attribute; frees object exactly once.

// Detach the object from its parent/parser so it can be independently managed
json_disconnect(o);
FUZZ_SET_ATTR_INT(o, "owned_by_parser", 0);
FUZZ_SET_ATTR_INT(o, "json_type", (int) o->type);
// Validation: maintains object as output and marks ownership transferred to caller for safe later json_free.

// Ensure the input object is a JSON hash/object before lookup
int t = FUZZ_GET_ATTR_INT(o, "json_type");
if (t != (int) JSON_HASH) { FUZZ_BAIL(); }

// Use a fuzzed key; empty or arbitrary bytes are allowed by API (may just return NULL)
std::string key = FUZZ_PARAM_STR();
json_object *child = json_hash_get(o, key.c_str());
if (!child) { FUZZ_BAIL(); }

// Disconnect child so it can be managed independently by the harness pool
json_disconnect(child);
FUZZ_SET_ATTR_INT(child, "owned_by_parser", 0);
FUZZ_SET_ATTR_INT(child, "json_type", (int) child->type);
// Validation: enforces object type precondition; ensures non-null child and safe ownership by disconnecting.

// Serialize the JSON object to a heap-allocated C string
char *s = json_stringify(o);
if (!s) { FUZZ_BAIL(); }

// Optionally exercise the buffer briefly, then free to avoid leaks
volatile size_t probe = 0; // prevent over-optimization
for (const char *p = s; *p && probe < 64; ++p) { probe += (unsigned char)(*p); }
free(s);
