// Construct a drawvec (std::vector<draw>) and populate with a few valid draw commands
// Keep coordinates within 40-bit signed range to match draw's bitfields
const long long LIM = (1LL << 39) - 1; // [-2^39, 2^39-1]

// Allocate on heap for persistence across stubs
drawvec *geom = new drawvec();

// Choose a small number of commands for performance
unsigned int n = (*FUZZ_PARAM(unsigned int) % 5) + 1; // 1..5
for (unsigned int i = 0; i < n; i++) {
    int op_choices[3] = {1, 2, 7};
