    long long rx = (long long)(*FUZZ_PARAM(long long));
    long long ry = (long long)(*FUZZ_PARAM(long long));
    long long x = rx;
    long long y = ry;
    if (x > LIM) x = LIM; if (x < -LIM) x = -LIM;
    if (y > LIM) y = LIM; if (y < -LIM) y = -LIM;
    geom->emplace_back(draw(op, x, y));
