// Optionally pre-seed keys/values maps with one entry to exercise constant pools
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) {
    mvt_feature feat;
    feat.type = (int)((*FUZZ_PARAM(unsigned int) % 3) + 1); // 1..3 (point/line/polygon)
