FUZZ_SET_ATTR_INT(layer, "initialized", 1);

// Choose a valid z in [0,22] and derive x,y in [0, 2^z - 1]
unsigned int uz = *FUZZ_PARAM(unsigned int) % 23u;
int z = (int)uz;
unsigned long long max_xy = (uz == 0 ? 0ULL : ((1ULL << uz) - 1ULL));
int x = (int)(max_xy == 0 ? 0 : (*FUZZ_PARAM(unsigned int) % (max_xy + 1ULL)));
int y = (int)(max_xy == 0 ? 0 : (*FUZZ_PARAM(unsigned int) % (max_xy + 1ULL)));

// Allocate the zxy on heap
zxy *tile = new zxy(z, x, y);
// Leave default extension .pbf
FUZZ_SET_ATTR_INT(tile, "z", z);

// Allocate a new mapping and populate a few entries
std::map<std::string, std::vector<std::string>> *mapping = new std::map<std::string, std::vector<std::string>>();
unsigned int keys = (*FUZZ_PARAM(unsigned int) % 4) + 1; // 1..4 keys
for (unsigned int i = 0; i < keys; i++) {
