import os
import random
import string
from typing import List

def _rand_filename(rng: random.Random, base_dir: str, ext_opts: List[str]) -> str:
    # Compose a short, safe filename with optional nested dirs
    depth = rng.choice([0, 1, 2])
    parts = []
    for _ in range(depth):
        name = ''.join(rng.choices(string.ascii_letters + string.digits + "-_", k=rng.randint(3, 8)))
        parts.append(name)
    stem = ''.join(rng.choices(string.ascii_letters + string.digits + "-_", k=rng.randint(5, 12)))
    ext = rng.choice(ext_opts)
    parts.append(stem + ext)
    path = os.path.join(base_dir, *parts)
    # Ensure directories exist
    d = os.path.dirname(path)
    if d and not os.path.exists(d):
        os.makedirs(d, exist_ok=True)
    return path

def _gen_csv(rng: random.Random) -> bytes:
    # Generate a small but varied CSV content
    rows = []
    # Header
    headers = ["id", "name", "value", "note"]
    rows.append(','.join(headers))
    # A few data rows with quoting, commas, numbers
    nrows = rng.randint(3, 8)
    for i in range(nrows):
        idv = str(i if rng.random() < 0.7 else rng.randint(-1000, 1000))
        name = rng.choice([
            "Alice", "Bob", "Carol", "Dörte", "张伟", "O\"Reilly", "Smith, Jr."])
        # Quote fields that contain commas or quotes
        def q(s: str) -> str:
            if any(c in s for c in [',', '"', '\n', '\r']):
                return '"' + s.replace('"', '""') + '"'
            return s
        value = rng.choice([
            f"{rng.uniform(-100,100):.6f}",
            str(rng.randint(0, 10**6)),
            "",
        ])
        note_opts = [
            "simple",
            "multi word",
            "embedded,comma",
            "quote\"inside",
            "line\nbreak",
            "utf8-✓",
        ]
        note = rng.choice(note_opts)
        row = [q(idv), q(name), q(value), q(note)]
        rows.append(','.join(row))
    content = '\n'.join(rows) + '\n'
    return content.encode('utf-8')

def _gen_json_filter(rng: random.Random) -> bytes:
    # Produce small valid JSON objects representing simple filters
    # Keep it generic: {"op":"==","key":"name","value":"Alice"}
    ops = ["==", "!=", ">", "<", ">=", "<=", "in", "has"]
    keys = ["id", "name", "value", "note", "flag", "count"]
    # Random value: number, string, bool, null, array
    def rand_json_value():
        choice = rng.random()
        if choice < 0.25:
            return rng.randint(-1000, 1000)
        elif choice < 0.5:
            return rng.choice(["Alice", "Bob", "Carol", "Δelta", "тест", "emoji-😀"]) 
        elif choice < 0.65:
            return rng.choice([True, False])
        elif choice < 0.8:
            return None
        else:
            arr = []
            for _ in range(rng.randint(1, 5)):
                arr.append(rng.choice([rng.randint(0, 10), rng.choice(["x","y","z"]) ]))
            return arr
    obj = {
        "op": rng.choice(ops),
        "key": rng.choice(keys),
        "value": rand_json_value()
    }
    # Occasionally nest
    if rng.random() < 0.3:
        obj = {"and": [obj, {"op": rng.choice(ops), "key": rng.choice(keys), "value": rand_json_value()}]}
    import json
    return json.dumps(obj, ensure_ascii=False).encode('utf-8')

def _gen_random_blob(rng: random.Random, min_len=32, max_len=1024) -> bytes:
    length = rng.randint(min_len, max_len)
    # Mix texty and binary
    if rng.random() < 0.6:
        # Mostly UTF-8 text
        alphabet = string.ascii_letters + string.digits + " \t,.;:'\"{}[]()\n\r-_/\\|!@#$%^&*+?=<>~"
        s = ''.join(rng.choices(alphabet, k=length))
        return s.encode('utf-8', errors='ignore')
    else:
        return bytes(rng.getrandbits(8) for _ in range(length))

def _gen_geojson_like(rng: random.Random) -> bytes:
    # Create a minimal GeoJSON FeatureCollection with a few features
    import json
    def rand_point():
        # Keep within common bounds
        lon = rng.uniform(-180, 180)
        lat = rng.uniform(-85, 85)
        return {"type": "Point", "coordinates": [lon, lat]}
    def rand_props():
        return {
            "name": rng.choice(["Alice", "Bob", "Park", "River", "道路", "Straße"]),
            "id": rng.randint(0, 100000),
            "value": rng.choice([rng.randint(-100,100), rng.uniform(-10,10), None, True, False]),
        }
    features = []
    for _ in range(rng.randint(1, 5)):
        features.append({
            "type": "Feature",
            "geometry": rand_point(),
            "properties": rand_props()
        })
    fc = {"type": "FeatureCollection", "features": features}
    return json.dumps(fc, ensure_ascii=False).encode('utf-8')

def _populate_file(path: str, data: bytes) -> None:
    with open(path, 'wb') as f:
        # Trim to limit 4096 bytes total per output buffer target; files can be larger, but keep reasonable
        f.write(data)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create a temporary workspace under current directory to avoid relying on system temp
    base = os.path.abspath("fuzz_tmp")
    os.makedirs(base, exist_ok=True)

    # Decide what the consumer likely wants based on fuzzer stubs:
    # - Some stubs expect CSV (readcsv, csv_getline)
    # - Some expect JSON (read_filter, json_begin_file)
    # - Some just want an existing file path (mbtiles_open, memfile_open)
    # We'll create multiple files and return one path. The runtime may reuse the same buffer for several calls.

    ext_opts = [".csv", ".json", ".txt", ".bin"]

    choice = rng.random()
    if choice < 0.35:
        # CSV file
        path = _rand_filename(rng, base, [".csv"]) 
        _populate_file(path, _gen_csv(rng))
    elif choice < 0.7:
        # JSON filter or GeoJSON file
        path = _rand_filename(rng, base, [".json"]) 
        data = _gen_json_filter(rng) if rng.random() < 0.6 else _gen_geojson_like(rng)
        _populate_file(path, data)
    else:
        # Random blob or small text
        path = _rand_filename(rng, base, [rng.choice(ext_opts)])
        _populate_file(path, _gen_random_blob(rng))

    # Return the path as bytes (UTF-8). Consumers use FUZZ_PARAM_FILENAME which expects a filename to an existing file.
    # Keep under 4096 bytes.
    p = path.encode('utf-8')
    if len(p) > 4096:
        p = p[:4096]
    return p
